def json_schema(_) do
  %{
    type: "object",
    properties: %{
      amount: %{type: "string", pattern: "^-?\\d+(\\.\\d+)?$"},
      currency: %{type: "string"}
    },
    example: %{amount: "100.00", currency: "USD"},
    required: ["amount", "currency"]
  }
end

def atom(input, options) do
  input = String.downcase(input)

  Enum.reduce_while(options, {:error, "Invalid input `#{input}`"}, fn option, error ->
    if input == to_string(option) do
      {:halt, {:ok, option}}
    else
      {:cont, error}
    end
  end)
end

def filter(input) when is_binary(input) do
  {:ok, input}
end
def filter(input) do
  {:error, "Invalid filter `#{inspect(input)}`"}
end

def filter_stdin(input) do
  {:ok, input > 0}
end

