  {:ok, width * height * 4}
end
def frame_size(format, width, height)
    when format in [:I420_10LE, :I420_10BE] and Integer.is_even(width) and Integer.is_even(height) do
  {:ok, 3 * width * height}
end
def frame_size(format, width, height)
    when format in [:I422_10LE, :I422_10BE] and Integer.is_even(width) do
  {:ok, 4 * width * height}
end
